CREATE TABLE star_orders (
  payload TEXT PRIMARY KEY, user_id INTEGER NOT NULL, sku TEXT NOT NULL,
  stars INTEGER NOT NULL CHECK (stars > 0), expires_at INTEGER NOT NULL,
  state TEXT NOT NULL DEFAULT 'pending', charge_id TEXT UNIQUE
);
CREATE INDEX star_orders_owner ON star_orders(user_id, sku, state);
CREATE TABLE star_payments (
  charge_id TEXT PRIMARY KEY, payload TEXT NOT NULL, user_id INTEGER NOT NULL,
  currency TEXT NOT NULL, amount INTEGER NOT NULL, state TEXT NOT NULL,
  reason TEXT, received_at INTEGER NOT NULL
);
CREATE TABLE star_access (
  charge_id TEXT PRIMARY KEY REFERENCES star_payments(charge_id),
  user_id INTEGER NOT NULL, sku TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1
);
CREATE INDEX star_access_owner ON star_access(user_id, sku, active);
CREATE TABLE star_refunds (
  charge_id TEXT PRIMARY KEY REFERENCES star_payments(charge_id),
  state TEXT NOT NULL DEFAULT 'sending', requested_at INTEGER NOT NULL
);

/** @param array<string, mixed> $query */
function preCheckout(PDO $db, array $query): bool
{
    $from = $query['from'] ?? null;
    $userId = is_array($from) ? ($from['id'] ?? null) : null;
    $payload = $query['invoice_payload'] ?? null;
    if (!is_int($userId) || !is_string($payload) || ($query['currency'] ?? null) !== 'XTR'
        || !is_int($query['total_amount'] ?? null)) return false;
    $q = $db->prepare("SELECT * FROM star_orders WHERE payload = ? AND user_id = ? AND state = 'pending'");
    $q->execute([$payload, $userId]);
    $order = row($q);
    if ($order && !is_string($order['sku'])) throw new RuntimeException('Некорректный товар в БД');
    return $order && (int) $order['expires_at'] > time()
        && (int) $order['stars'] === $query['total_amount'] && !hasCourseAccess($db, $userId, $order['sku']);
}

/** @param array<string, mixed> $payment */
function recordPayment(PDO $db, int $userId, array $payment, bool $refund = false): string
{
    $charge = $payment['telegram_payment_charge_id'] ?? null;
    $payload = $payment['invoice_payload'] ?? null;
    $currency = $payment['currency'] ?? null;
    $amount = $payment['total_amount'] ?? null;
    if (!is_string($charge) || $charge === '' || !is_string($payload) || $payload === ''
        || !is_string($currency) || $currency === '' || !is_int($amount) || $amount <= 0) {
        throw new InvalidArgumentException('Некорректный платёж');
    }
    $payment = ['telegram_payment_charge_id' => $charge, 'invoice_payload' => $payload,
        'currency' => $currency, 'total_amount' => $amount];
    return atomic($db, function () use ($db, $userId, $payment, $refund): string {
        $charge = $payment['telegram_payment_charge_id'];
        $payload = $payment['invoice_payload'];
        $q = $db->prepare('SELECT * FROM star_payments WHERE charge_id = ?');
        $q->execute([$charge]);
        $existing = row($q);
        if ($existing && !is_string($existing['state'])) throw new RuntimeException('Некорректный статус в БД');
        if ($existing && ((int) $existing['user_id'] !== $userId || $existing['payload'] !== $payload
            || $existing['currency'] !== $payment['currency'] || (int) $existing['amount'] !== $payment['total_amount'])) {
            throw new RuntimeException('Конфликт идентификатора платежа: нужна сверка');
        }
        if ($existing && (!$refund || $existing['state'] === 'refunded')) return $existing['state'];
        $q = $db->prepare('SELECT * FROM star_orders WHERE payload = ?');
        $q->execute([$payload]);
        $order = row($q);
        if ($order && !is_string($order['sku'])) throw new RuntimeException('Некорректный товар в БД');
        $matches = $order && (int) $order['user_id'] === $userId && $payment['currency'] === 'XTR'
            && (int) $order['stars'] === $payment['total_amount'];
        $duplicatePurchase = $matches && !$refund &&
            (($order['charge_id'] !== null && $order['charge_id'] !== $charge)
             || hasCourseAccess($db, $userId, $order['sku']));
        $state = $refund ? 'refunded' : ($matches && !$duplicatePurchase ? 'paid' : 'review');
        $reason = !$matches ? 'order_mismatch' : ($duplicatePurchase ? 'extra_payment' : null);
        $db->prepare('INSERT INTO star_payments
            (charge_id, payload, user_id, currency, amount, state, reason, received_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(charge_id) DO UPDATE SET state = excluded.state, reason = excluded.reason')
            ->execute([$charge, $payload, $userId, $payment['currency'], $payment['total_amount'], $state, $reason, time()]);
        if ($refund) {
            $db->prepare('UPDATE star_access SET active = 0 WHERE charge_id = ?')->execute([$charge]);
            $db->prepare("UPDATE star_refunds SET state = 'done' WHERE charge_id = ?")->execute([$charge]);
        }
        if ($matches && $state === 'paid') {
            $db->prepare('INSERT INTO star_access (charge_id, user_id, sku) VALUES (?, ?, ?)')
                ->execute([$charge, $userId, $order['sku']]);
        }
        if ($matches && in_array($state, ['paid', 'refunded'], true)) {
            $db->prepare('UPDATE star_orders SET state = ?, charge_id = ?
                WHERE payload = ? AND (charge_id IS NULL OR charge_id = ?)')
                ->execute([$state, $charge, $payload, $charge]);
        }
        return $state;
    });
}

/** @param callable(string, array<string, mixed>): array{state: string, result?: mixed, code?: int, retry_after?: int} $call */
function refundPayment(PDO $db, string $charge, callable $call): string
{
    $payment = atomic($db, function () use ($db, $charge) {
        $q = $db->prepare("SELECT * FROM star_payments WHERE charge_id = ? AND state IN ('paid', 'review') AND currency = 'XTR'");
        $q->execute([$charge]);
        $payment = row($q);
        if (!$payment) return null;
        $q = $db->prepare('INSERT INTO star_refunds (charge_id, requested_at) VALUES (?, ?) ON CONFLICT DO NOTHING');
        $q->execute([$charge, time()]);
        return $q->rowCount() === 1 ? $payment : null;
    });
    if (!$payment) return 'already_processed_or_requires_review';
    $result = $call('refundStarPayment', ['user_id' => (int) $payment['user_id'],
        'telegram_payment_charge_id' => $charge]);
    if ($result['state'] === 'ok' && ($result['result'] ?? null) === true) {
        recordPayment($db, (int) $payment['user_id'], [
            'telegram_payment_charge_id' => $charge, 'invoice_payload' => $payment['payload'],
            'currency' => $payment['currency'], 'total_amount' => (int) $payment['amount'],
        ], true);
        return 'refunded';
    }
    $state = $result['state'] === 'rejected' ? 'failed' : 'unknown';
    $db->prepare("UPDATE star_refunds SET state = ? WHERE charge_id = ? AND state = 'sending'")
        ->execute([$state, $charge]);
    return $state;
}

